source='''from collections import Counter


def transform(grid):
    """Continue incomplete right-edge line patterns with the task marker color."""
    h, w = len(grid), len(grid[0])
    counts = Counter(x for row in grid for x in row)
    bg = counts.most_common(1)[0][0]
    foreground_counts = Counter(x for row in grid for x in row if x != bg)
    if not foreground_counts:
        return [row[:] for row in grid]
    fg = foreground_counts.most_common(1)[0][0]
    out = [row[:] for row in grid]

    # Blank rows separate the repeated horizontal pattern groups.
    groups = []
    r = 0
    while r < h:
        if all(x == bg for x in grid[r]):
            r += 1
            continue
        start = r
        while r < h and any(x != bg for x in grid[r]):
            r += 1
        end = r
        rightmost = max(
            c for rr in range(start, end)
            for c, value in enumerate(grid[rr]) if value == fg
        )
        groups.append((start, end, rightmost))

    farthest = max(group[2] for group in groups)
    for group_index, (start, end, rightmost) in enumerate(groups):
        # The longest-reaching group is the reference; shorter groups can be
        # completed toward its right edge.
        if rightmost >= farthest:
            continue
        for rr in range(start, end):
            row = grid[rr]
            fg_cols = [c for c, value in enumerate(row) if value == fg]
            if not fg_cols:
                continue
            last = fg_cols[-1]
            if last == w - 1:
                continue
            suffix = range(last + 1, w)
            run = 1
            while last - run >= 0 and row[last - run] == fg:
                run += 1

            # A solid bar from the left continues through the empty suffix.
            if row[0] == fg:
                first_bg = next((c for c, value in enumerate(row) if value == bg), w)
                if all(value == bg for value in row[first_bg:]):
                    for c in suffix:
                        out[rr][c] = 1
                    continue

            # Extend a strong terminal run when only a short gap remains.
            if run >= 3 and w - last - 1 < run:
                for c in suffix:
                    out[rr][c] = 1
                continue

            # The upper incomplete group can encode an alternating tail.
            if group_index == 0 and last >= 3:
                tail = row[last - 3:last + 1]
                if all(tail[i] != tail[i + 1] for i in range(3)):
                    for c in suffix:
                        if (c - last) % 2 == 0:
                            out[rr][c] = 1
                    continue

                # An adjacent row with a complete alternating tail can reveal
                # the opposite phase for a one-cell ending.
                neighbor = None
                for nr in (rr - 1, rr + 1):
                    if start <= nr < end:
                        nfg_cols = [c for c, value in enumerate(grid[nr]) if value == fg]
                        if len(nfg_cols) >= 4:
                            nlast = nfg_cols[-1]
                            if nlast >= 3:
                                ntail = grid[nr][nlast - 3:nlast + 1]
                                if all(ntail[i] != ntail[i + 1] for i in range(3)):
                                    neighbor = nr
                                    break
                if neighbor is not None and last >= 1 and row[last - 1] == bg:
                    nlast = max(c for c, value in enumerate(grid[neighbor]) if value == fg)
                    if (nlast >= last - 1 and grid[neighbor][last - 1] == fg
                            and grid[neighbor][last] == bg):
                        for c in suffix:
                            if (c - last) % 2 == 0:
                                out[rr][c] = 1
    return out
'''
